#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_add_digit_existing_node_with_next_digit(void) {
    // Setup: Create a big_int list with at least two nodes.
    // First, create head node.
    big_int *head = add_digit(NULL, '1');
    TEST_ASSERT_NOT_NULL(head);
    // Add a second node, making head->next_digit non-NULL.
    big_int *second = add_digit(head, '2');
    TEST_ASSERT_NOT_NULL(second);
    // Now head->next_digit points to second.
    // The target path requires digit != NULL and digit->next_digit != NULL.
    // We will call add_digit with digit = head and a new value.
    char new_value = '9';

    // Test: Call add_digit on head, which already has a next_digit.
    // According to path 4, it should update digit->next_digit->value and return digit->next_digit.
    big_int *result = add_digit(head, new_value);

    // Assertions
    TEST_ASSERT_NOT_NULL(result);
    // Result should be the same as second (head->next_digit).
    TEST_ASSERT_EQUAL_PTR(second, result);
    // The value of second should be updated to new_value.
    TEST_ASSERT_EQUAL_CHAR(new_value, second->value);
    // The list structure should remain: head -> second -> NULL.
    TEST_ASSERT_NULL(second->next_digit);
    TEST_ASSERT_EQUAL_PTR(head, second->prev_digit);
    TEST_ASSERT_EQUAL_PTR(second, head->next_digit);
    TEST_ASSERT_NULL(head->prev_digit);

    // Cleanup
    helper_free_big_int(head);
}

